#!/usr/bin/env bash
# Validates Conventional Commit messages.
#   scripts/check-commit-msg.sh <file>          check a commit message file (commit-msg hook)
#   scripts/check-commit-msg.sh --range A..B    check every commit in a range (CI)
set -euo pipefail

TYPES='feat|fix|docs|test|refactor|perf|build|ci|chore|revert'
PATTERN="^(${TYPES})(\([a-z0-9][a-z0-9-]*\))?!?: [^ ].{0,98}$"

check_subject() {
  local subject="$1" ref="$2"
  # Merge and revert commits generated by git are allowed as-is.
  if [[ "$subject" =~ ^(Merge|Revert\ \") ]]; then return 0; fi
  if [[ ! "$subject" =~ $PATTERN ]]; then
    echo "✗ Invalid commit message${ref:+ ($ref)}: \"$subject\"" >&2
    echo "  Expected: <type>(<scope>): <summary>   types: ${TYPES//|/, }" >&2
    echo "  Example:  feat(ingress): verify Razorpay webhook signatures" >&2
    return 1
  fi
}

if [[ "${1:-}" == "--range" ]]; then
  status=0
  while IFS=$'\t' read -r sha subject; do
    check_subject "$subject" "${sha:0:7}" || status=1
  done < <(git log --format='%H%x09%s' "$2")
  exit $status
fi

subject="$(grep -v '^#' "$1" | head -n1)"
check_subject "$subject" ""
